var builtinVariables = [...]Variable{
	{Name: "v:count", Type: "number", Flags: VariableCompatible | VariableReadOnly, Documentation: "v:count\t\tThe count given for the last Normal mode command.  Can be used\nto get the count before a mapping.  Read-only.  Example:\n```vim\n:map _x :<C-U>echo \"the count is \" .. v:count<CR>\n```\nNote: The <C-U> is required to remove the line range that you\nget when typing ':' after a count.\nWhen there are two counts, as in \"3d2w\", they are multiplied,\njust like what happens in the command, \"d6w\" for the example.\nAlso used for evaluating the 'formatexpr' option.\n\"count\" also works, for backwards compatibility, unless\n`scriptversion` is 3 or higher.", DocumentationSource: "eval.txt"},
	{Name: "v:count1", Type: "number", Flags: VariableReadOnly, Documentation: "v:count1\tJust like \"v:count\", but defaults to one when no count is\nused.", DocumentationSource: "eval.txt"},
	{Name: "v:prevcount", Type: "number", Flags: VariableReadOnly, Documentation: "v:prevcount\tThe count given for the last but one Normal mode command.\nThis is the v:count value of the previous command.  Useful if\nyou want to cancel Visual or Operator-pending mode and then\nuse the count, e.g.:\n```vim\n\t\t:vmap % <Esc>:call MyFilter(v:prevcount)<CR>\n```\nRead-only.", DocumentationSource: "eval.txt"},
	{Name: "v:errmsg", Type: "string", Flags: VariableCompatible, Documentation: "v:errmsg\tLast error message that occurred (not necessarily displayed).\nIt's allowed to set this variable.  Example:\n```vim\n:let v:errmsg = \"\"\n:silent! next\n:if v:errmsg != \"\"\n:  ... handle error\n```\n\"errmsg\" also works, for backwards compatibility, unless\n`scriptversion` is 3 or higher.", DocumentationSource: "eval.txt"},
	{Name: "v:warningmsg", Type: "string", Flags: 0, Documentation: "v:warningmsg\tLast given warning message.  It's allowed to set this\nvariable.", DocumentationSource: "eval.txt"},
	{Name: "v:statusmsg", Type: "string", Flags: 0, Documentation: "v:statusmsg\tLast given status message.  It's allowed to set this variable.", DocumentationSource: "eval.txt"},
	{Name: "v:shell_error", Type: "number", Flags: VariableCompatible | VariableReadOnly, Documentation: "v:shell_error\tResult of the last shell command.  When non-zero, the last\nshell command had an error.  When zero, there was no problem.\nThis only works when the shell returns the error code to Vim.\nThe value -1 is often used when the command could not be\nexecuted.  Read-only.\nExample:\n```vim\n:!mv foo bar\n:if v:shell_error\n:  echo 'could not rename \"foo\" to \"bar\"!'\n:endif\n```\n\"shell_error\" also works, for backwards compatibility, unless\n`scriptversion` is 3 or higher.", DocumentationSource: "eval.txt"},
	{Name: "v:this_session", Type: "string", Flags: VariableCompatible, Documentation: "v:this_session\tFull filename of the last loaded or saved session file.  See\n`:mksession`.  It is allowed to set this variable.  When no\nsession file has been saved, this variable is empty.\n\"this_session\" also works, for backwards compatibility, unless\n`scriptversion` is 3 or higher", DocumentationSource: "eval.txt"},
	{Name: "v:version", Type: "number", Flags: VariableCompatible | VariableReadOnly, Documentation: "v:version\tVersion number of Vim: Major version number times 100 plus\nminor version number.  Version 5.0 is 500.  Version 5.1\nis 501.  Read-only.  \"version\" also works, for backwards\ncompatibility, unless `scriptversion` is 3 or higher.\nUse `has()` to check if a certain patch was included, e.g.:\n```vim\n\t\tif has(\"patch-7.4.123\")\n```\nNote that patch numbers are specific to the version, thus both\nversion 5.0 and 5.1 may have a patch 123, but these are\ncompletely different.", DocumentationSource: "eval.txt"},
	{Name: "v:lnum", Type: "number", Flags: VariableSandboxReadOnly, Documentation: "v:lnum\t\tLine number for the 'foldexpr' `fold-expr`, 'formatexpr' and\n'indentexpr' expressions, tab page number for 'guitablabel'\nand 'guitabtooltip'.  Only valid while one of these\nexpressions is being evaluated.  Read-only when in the\n`sandbox`.", DocumentationSource: "eval.txt"},
	{Name: "v:termresponse", Type: "string", Flags: VariableReadOnly, Documentation: "v:termresponse\tThe escape sequence returned by the terminal for the `t_RV`\ntermcap entry.  It is set when Vim receives an escape sequence\nthat starts with ESC [ or CSI, then '>' or '?' and ends in a\n'c', with only digits and ';' in between.\nWhen this variable is set, the TermResponse autocommand event\nis fired, so that you can react to the response from the\nterminal.  The TermResponseAll event is also fired, with\n<amatch> set to \"version\".  You can use `terminalprops()` to\nsee what Vim figured out about the terminal.\nThe response from a new xterm is: \"<Esc>[> Pp ; Pv ; Pc c\".\nPp is the terminal type: 0 for vt100 and 1 for vt220.  Pv is\nthe patch level (since this was introduced in patch 95, it's\nalways 95 or higher).  Pc is always zero.\nIf Pv is 141 or higher then Vim will try to request terminal\ncodes.  This only works with xterm `xterm-codes`.\n{only when compiled with `+termresponse` feature}", DocumentationSource: "eval.txt"},
	{Name: "v:fname", Type: "string", Flags: VariableReadOnly, Documentation: "v:fname\t\tWhen evaluating 'includeexpr': the file name that was\ndetected.  Empty otherwise.", DocumentationSource: "eval.txt"},
	{Name: "v:lang", Type: "string", Flags: VariableReadOnly, Documentation: "v:lang\t\tThe current locale setting for messages of the runtime\nenvironment.  This allows Vim scripts to be aware of the\ncurrent language.  Technical: it's the value of LC_MESSAGES.\nThe value is system dependent.\nThis variable can not be set directly, use the `:language`\ncommand.\nIt can be different from `v:ctype` when messages are desired\nin a different language than what is used for character\nencoding.  See `multi-lang`.", DocumentationSource: "eval.txt"},
	{Name: "v:lc_time", Type: "string", Flags: VariableReadOnly, Documentation: "v:lc_time\tThe current locale setting for time messages of the runtime\nenvironment.  This allows Vim scripts to be aware of the\ncurrent language.  Technical: it's the value of LC_TIME.\nThis variable can not be set directly, use the `:language`\ncommand.  See `multi-lang`.", DocumentationSource: "eval.txt"},
	{Name: "v:ctype", Type: "string", Flags: VariableReadOnly, Documentation: "v:ctype\t\tThe current locale setting for characters of the runtime\nenvironment.  This allows Vim scripts to be aware of the\ncurrent locale encoding.  Technical: it's the value of\nLC_CTYPE.  When not using a locale the value is \"C\".\nThis variable can not be set directly, use the `:language`\ncommand.\nSee `multi-lang`.", DocumentationSource: "eval.txt"},
	{Name: "v:charconvert_from", Type: "string", Flags: VariableReadOnly, Documentation: "v:charconvert_from\nThe name of the character encoding of a file to be converted.\nOnly valid while evaluating the 'charconvert' option.", DocumentationSource: "eval.txt"},
	{Name: "v:charconvert_to", Type: "string", Flags: VariableReadOnly, Documentation: "v:charconvert_to\nThe name of the character encoding of a file after conversion.\nOnly valid while evaluating the 'charconvert' option.", DocumentationSource: "eval.txt"},
	{Name: "v:fname_in", Type: "string", Flags: VariableReadOnly, Documentation: "v:fname_in\tThe name of the input file.  Valid while evaluating:\n### option\t\tused for\n'charconvert'\tfile to be converted\n'diffexpr'\toriginal file\n'patchexpr'\toriginal file\n'printexpr'\tfile to be printed\nAnd set to the swap file name for `SwapExists`.", DocumentationSource: "eval.txt"},
	{Name: "v:fname_out", Type: "string", Flags: VariableReadOnly, Documentation: "v:fname_out\tThe name of the output file.  Only valid while\nevaluating:\n### option\t\tused for\n'charconvert'\tresulting converted file (*)\n'diffexpr'\toutput of diff\n'patchexpr'\tresulting patched file\n(*) When doing conversion for a write command (e.g., \":w\nfile\") it will be equal to v:fname_in.  When doing conversion\nfor a read command (e.g., \":e file\") it will be a temporary\nfile and different from v:fname_in.", DocumentationSource: "eval.txt"},
	{Name: "v:fname_new", Type: "string", Flags: VariableReadOnly, Documentation: "v:fname_new\tThe name of the new version of the file.  Only valid while\nevaluating 'diffexpr'.", DocumentationSource: "eval.txt"},
	{Name: "v:fname_diff", Type: "string", Flags: VariableReadOnly, Documentation: "v:fname_diff\tThe name of the diff (patch) file.  Only valid while\nevaluating 'patchexpr'.", DocumentationSource: "eval.txt"},
	{Name: "v:cmdarg", Type: "string", Flags: VariableReadOnly, Documentation: "v:cmdarg\tThis variable is used for two purposes:\n1. The extra arguments given to a file read/write command.\nCurrently these are \"++enc=\" and \"++ff=\".  This variable is\nset before an autocommand event for a file read/write\ncommand is triggered.  There is a leading space to make it\npossible to append this variable directly after the\nread/write command.  Note: The \"+cmd\" argument isn't\nincluded here, because it will be executed anyway.\n2. When printing a PostScript file with \":hardcopy\" this is\nthe argument for the \":hardcopy\" command.  This can be used\nin 'printexpr'.", DocumentationSource: "eval.txt"},
	{Name: "v:foldstart", Type: "number", Flags: VariableSandboxReadOnly, Documentation: "v:foldstart\tUsed for 'foldtext': first line of closed fold.\nRead-only in the `sandbox`. `fold-foldtext`", DocumentationSource: "eval.txt"},
	{Name: "v:foldend", Type: "number", Flags: VariableSandboxReadOnly, Documentation: "v:foldend\tUsed for 'foldtext': last line of closed fold.\nRead-only in the `sandbox`. `fold-foldtext`", DocumentationSource: "eval.txt"},
	{Name: "v:folddashes", Type: "string", Flags: VariableSandboxReadOnly, Documentation: "v:folddashes\tUsed for 'foldtext': dashes representing foldlevel of a closed\nfold.\nRead-only in the `sandbox`. `fold-foldtext`", DocumentationSource: "eval.txt"},
	{Name: "v:foldlevel", Type: "number", Flags: VariableSandboxReadOnly, Documentation: "v:foldlevel\tUsed for 'foldtext': foldlevel of closed fold.\nRead-only in the `sandbox`. `fold-foldtext`", DocumentationSource: "eval.txt"},
	{Name: "v:progname", Type: "string", Flags: VariableReadOnly, Documentation: "v:progname\tContains the name (with path removed) with which Vim was\ninvoked.  Allows you to do special initialisations for `view`,\n`evim` etc., or any other name you might symlink to Vim.\nRead-only.", DocumentationSource: "eval.txt"},
	{Name: "v:servername", Type: "string", Flags: VariableReadOnly, Documentation: "v:servername\tThe resulting registered `client-server-name` if any.\nRead-only.", DocumentationSource: "eval.txt"},
	{Name: "v:dying", Type: "number", Flags: VariableReadOnly, Documentation: "v:dying\t\tNormally zero.  When a deadly signal is caught it's set to\none.  When multiple signals are caught the number increases.\nCan be used in an autocommand to check if Vim didn't\nterminate normally. {only works on Unix}\nExample:\n```vim\n:au VimLeave * if v:dying | echo \"\\nAAAAaaaarrrggghhhh!!!\\n\" | endif\n```\nNote: if another deadly signal is caught when v:dying is one,\nVimLeave autocommands will not be executed.", DocumentationSource: "eval.txt"},
	{Name: "v:exception", Type: "string", Flags: VariableReadOnly, Documentation: "v:exception\tThe value of the exception most recently caught and not\nfinished.  See also `v:stacktrace`, `v:throwpoint`, and\n`throw-variables`.\nExample:\n```vim\n:try\n:  throw \"oops\"\n:catch /.*/\n:  echo \"caught \" .. v:exception\n:endtry\n```\nOutput: \"caught oops\".", DocumentationSource: "eval.txt"},
	{Name: "v:throwpoint", Type: "string", Flags: VariableReadOnly, Documentation: "v:throwpoint\tThe point where the exception most recently caught and not\nfinished was thrown.  Not set when commands are typed.  See\nalso `v:exception`, `v:stacktrace`, and `throw-variables`.\nExample:\n```vim\n:try\n:  throw \"oops\"\n:catch /.*/\n:  echo \"Exception from\" v:throwpoint\n:endtry\n```\nOutput: \"Exception from test.vim, line 2\"", DocumentationSource: "eval.txt"},
	{Name: "v:register", Type: "string", Flags: VariableReadOnly, Documentation: "v:register\tThe name of the register in effect for the current normal mode\ncommand (regardless of whether that command actually used a\nregister).  Or for the currently executing normal mode mapping\n(use this in custom commands that take a register).\nIf none is supplied it is the default register '\"', unless\n'clipboard' contains \"unnamed\" or \"unnamedplus\", then it is\n'*' or '+'.\nAlso see `getreg()` and `setreg()`", DocumentationSource: "eval.txt"},
	{Name: "v:cmdbang", Type: "number", Flags: VariableReadOnly, Documentation: "v:cmdbang\tSet like v:cmdarg for a file read/write command.  When a \"!\"\nwas used the value is 1, otherwise it is 0.  Note that this\ncan only be used in autocommands.  For user commands `<bang>`\ncan be used.", DocumentationSource: "eval.txt"},
	{Name: "v:insertmode", Type: "string", Flags: VariableReadOnly, Documentation: "v:insertmode\tUsed for the `InsertEnter` and `InsertChange` autocommand\nevents.  Values:\ni\tInsert mode\nr\tReplace mode\nv\tVirtual Replace mode", DocumentationSource: "eval.txt"},
	{Name: "v:val", Type: "any", Flags: VariableReadOnly, Documentation: "v:val\t\tValue of the current item of a `List` or `Dictionary`.  Only\nvalid while evaluating the expression used with `map()` and\n`filter()`.  Read-only.", DocumentationSource: "eval.txt"},
	{Name: "v:key", Type: "any", Flags: VariableReadOnly, Documentation: "v:key\t\tKey of the current item of a `Dictionary`.  Only valid while\nevaluating the expression used with `map()` and `filter()`.\nRead-only.", DocumentationSource: "eval.txt"},
	{Name: "v:profiling", Type: "number", Flags: VariableReadOnly, Documentation: "v:profiling\tNormally zero.  Set to one after using \":profile start\".\nSee `profiling`.", DocumentationSource: "eval.txt"},
	{Name: "v:fcs_reason", Type: "string", Flags: VariableReadOnly, Documentation: "v:fcs_reason\tThe reason why the `FileChangedShell` event was triggered.\nCan be used in an autocommand to decide what to do and/or what\nto set v:fcs_choice to.  Possible values:\ndeleted\t\tfile no longer exists\nconflict\tfile contents, mode or timestamp was\nchanged and buffer is modified\nchanged\t\tfile contents has changed\nmode\t\tmode of file changed\ntime\t\tonly file timestamp changed", DocumentationSource: "eval.txt"},
	{Name: "v:fcs_choice", Type: "string", Flags: 0, Documentation: "v:fcs_choice\tWhat should happen after a `FileChangedShell` event was\ntriggered.  Can be used in an autocommand to tell Vim what to\ndo with the affected buffer:\nreload\t\tReload the buffer (does not work if\nthe file was deleted).\nedit\t\tReload the buffer and detect the\nvalues for options such as\n'fileformat', 'fileencoding', 'binary'\n(does not work if the file was\ndeleted).\nask\t\tAsk the user what to do, as if there\nwas no autocommand.  Except that when\nonly the timestamp changed nothing\nwill happen.\n<empty>\t\tNothing, the autocommand should do\neverything that needs to be done.\nThe default is empty.  If another (invalid) value is used then\nVim behaves like it is empty, there is no warning message.", DocumentationSource: "eval.txt"},
	{Name: "v:beval_bufnr", Type: "number", Flags: VariableReadOnly, Documentation: "v:beval_bufnr\tThe number of the buffer, over which the mouse pointer is.\nOnly valid while evaluating the 'balloonexpr' option.", DocumentationSource: "eval.txt"},
	{Name: "v:beval_winnr", Type: "number", Flags: VariableReadOnly, Documentation: "v:beval_winnr\tThe number of the window, over which the mouse pointer is.\nOnly valid while evaluating the 'balloonexpr' option.  The\nfirst window has number zero (unlike most other places where a\nwindow gets a number).", DocumentationSource: "eval.txt"},
	{Name: "v:beval_winid", Type: "number", Flags: VariableReadOnly, Documentation: "v:beval_winid\tThe `window-ID` of the window, over which the mouse pointer\nis.  Otherwise like v:beval_winnr.", DocumentationSource: "eval.txt"},
	{Name: "v:beval_lnum", Type: "number", Flags: VariableReadOnly, Documentation: "v:beval_lnum\tThe number of the line, over which the mouse pointer is.  Only\nvalid while evaluating the 'balloonexpr' option.", DocumentationSource: "eval.txt"},
	{Name: "v:beval_col", Type: "number", Flags: VariableReadOnly, Documentation: "v:beval_col\tThe number of the column, over which the mouse pointer is.\nThis is the byte index in the `v:beval_lnum` line.\nOnly valid while evaluating the 'balloonexpr' option.", DocumentationSource: "eval.txt"},
	{Name: "v:beval_text", Type: "string", Flags: VariableReadOnly, Documentation: "v:beval_text\tThe text under or after the mouse pointer.  Usually a word as\nit is useful for debugging a C program.  'iskeyword' applies,\nbut a dot and \"->\" before the position is included.  When on a\n']' the text before it is used, including the matching '[' and\nword before it.  When on a Visual area within one line the\nhighlighted text is used.  Also see `<cexpr>`.\nOnly valid while evaluating the 'balloonexpr' option.", DocumentationSource: "eval.txt"},
	{Name: "v:scrollstart", Type: "string", Flags: 0, Documentation: "v:scrollstart\tString describing the script or function that caused the\nscreen to scroll up.  It's only set when it is empty, thus the\nfirst reason is remembered.  It is set to \"Unknown\" for a\ntyped command.\nThis can be used to find out why your script causes the\nhit-enter prompt.", DocumentationSource: "eval.txt"},
	{Name: "v:swapname", Type: "string", Flags: VariableReadOnly, Documentation: "v:swapname\tOnly valid when executing `SwapExists` autocommands: Name of\nthe swap file found.  Read-only.", DocumentationSource: "eval.txt"},
	{Name: "v:swapchoice", Type: "string", Flags: 0, Documentation: "v:swapchoice\t`SwapExists` autocommands can set this to the selected choice\nfor handling an existing swap file:\n'o'\tOpen read-only\n'e'\tEdit anyway\n'r'\tRecover\n'd'\tDelete swapfile\n'q'\tQuit\n'a'\tAbort\nThe value should be a single-character string.  An empty value\nresults in the user being asked, as would happen when there is\nno SwapExists autocommand.  The default is empty.", DocumentationSource: "eval.txt"},
	{Name: "v:swapcommand", Type: "string", Flags: VariableReadOnly, Documentation: "v:swapcommand\tNormal mode command to be executed after a file has been\nopened.  Can be used for a `SwapExists` autocommand to have\nanother Vim open the file and jump to the right place.  For\nexample, when jumping to a tag the value is \":tag tagname\\r\".\nFor \":edit +cmd file\" the value is \":cmd\\r\".", DocumentationSource: "eval.txt"},
	{Name: "v:char", Type: "string", Flags: 0, Documentation: "v:char\t\tArgument for evaluating 'formatexpr' and used for the typed\ncharacter when using <expr> in an abbreviation `:map-<expr>`.\nIt is also used by the `InsertCharPre`, `InsertEnter`,\n`KeyInputPre`, `CmdlineLeave` and `CmdlineLeavePre` events.", DocumentationSource: "eval.txt"},
	{Name: "v:mouse_win", Type: "number", Flags: 0, Documentation: "v:mouse_win\tWindow number for a mouse click obtained with `getchar()`.\nFirst window has number 1, like with `winnr()`.  The value is\nzero when there was no mouse button click.", DocumentationSource: "eval.txt"},
	{Name: "v:mouse_winid", Type: "number", Flags: 0, Documentation: "v:mouse_winid\tWindow ID for a mouse click obtained with `getchar()`.\nThe value is zero when there was no mouse button click.", DocumentationSource: "eval.txt"},
	{Name: "v:mouse_lnum", Type: "number", Flags: 0, Documentation: "v:mouse_lnum\tLine number for a mouse click obtained with `getchar()`.\nThis is the text line number, not the screen line number.  The\nvalue is zero when there was no mouse button click.", DocumentationSource: "eval.txt"},
	{Name: "v:mouse_col", Type: "number", Flags: 0, Documentation: "v:mouse_col\tColumn number for a mouse click obtained with `getchar()`.\nThis is the screen column number, like with `virtcol()`.  The\nvalue is zero when there was no mouse button click.", DocumentationSource: "eval.txt"},
	{Name: "v:operator", Type: "string", Flags: VariableReadOnly, Documentation: "v:operator\tThe last operator given in Normal mode.  This is a single\ncharacter except for commands starting with <g> or <z>,\nin which case it is two characters.  Best used alongside\n`v:prevcount` and `v:register`.  Useful if you want to cancel\nOperator-pending mode and then use the operator, e.g.:\n```vim\n\t\t:omap O <Esc>:call MyMotion(v:operator)<CR>\n```\nThe value remains set until another operator is entered, thus\ndon't expect it to be empty.\nv:operator is not set for `:delete`, `:yank` or other Ex\ncommands.\nRead-only.", DocumentationSource: "eval.txt"},
	{Name: "v:searchforward", Type: "number", Flags: 0, Documentation: "v:searchforward\nSearch direction:  1 after a forward search, 0 after a\nbackward search.  It is reset to forward when directly setting\nthe last search pattern, see `quote/`.\nNote that the value is restored when returning from a\nfunction. `function-search-undo`.\nRead-write.", DocumentationSource: "eval.txt"},
	{Name: "v:hlsearch", Type: "number", Flags: 0, Documentation: "v:hlsearch\tVariable that indicates whether search highlighting is on.\nSetting it makes sense only if 'hlsearch' is enabled which\nrequires `+extra_search`.  Setting this variable to zero acts\nlike the `:nohlsearch` command, setting it to one acts like\n```vim\n\t\tlet &hlsearch = &hlsearch\n```\nNote that the value is restored when returning from a\nfunction. `function-search-undo`.", DocumentationSource: "eval.txt"},
	{Name: "v:oldfiles", Type: "list<string>", Flags: 0, Documentation: "v:oldfiles\tList of file names that is loaded from the `viminfo` file on\nstartup.  These are the files that Vim remembers marks for.\nThe length of the List is limited by the ' argument of the\n'viminfo' option (default is 100).\nWhen the `viminfo` file is not used the List is empty.\nAlso see `:oldfiles` and `c_#<`.\nThe List can be modified, but this has no effect on what is\nstored in the `viminfo` file later.  If you use values other\nthan String this will cause trouble.\n{only when compiled with the `+viminfo` feature}", DocumentationSource: "eval.txt"},
	{Name: "v:windowid", Type: "number", Flags: VariableReadOnly, Documentation: "v:windowid\tWhen any X11 based GUI is running or when running in a\nterminal and Vim connects to the X server (`-X`) this will be\nset to the window ID.\nWhen an MS-Windows GUI is running this will be set to the\nwindow handle.\nOtherwise the value is zero.\nNote: for windows inside Vim use `winnr()` or `win_getid()`,\nsee `window-ID`.", DocumentationSource: "eval.txt"},
	{Name: "v:progpath", Type: "string", Flags: VariableReadOnly, Documentation: "v:progpath\tContains the command with which Vim was invoked, in a form\nthat when passed to the shell will run the same Vim executable\nas the current one (if $PATH remains unchanged).\nUseful if you want to message a Vim server using a\n`--remote-expr`.\nTo get the full path use:\n```vim\n\t\techo exepath(v:progpath)\n```\nIf the command has a relative path it will be expanded to the\nfull path, so that it still works after `:cd`.  Thus starting\n\"./vim\" results in \"/home/user/path/to/vim/src/vim\".\nOn Linux and other systems it will always be the full path.\nOn Mac it may just be \"vim\" and using exepath() as mentioned\nabove should be used to get the full path.\nOn MS-Windows the executable may be called \"vim.exe\", but the\n\".exe\" is not added to v:progpath.\nRead-only.", DocumentationSource: "eval.txt"},
	{Name: "v:completed_item", Type: "dict<string>", Flags: 0, Documentation: "v:completed_item\n`Dictionary` containing the `complete-items` for the most\nrecently completed word after `CompleteDone`.  The\n`Dictionary` is empty if the completion failed.\nNote: Plugins can modify the value to emulate the builtin\n`CompleteDone` event behavior.", DocumentationSource: "eval.txt"},
	{Name: "v:option_new", Type: "string", Flags: VariableReadOnly, Documentation: "v:option_new    New value of the option.  Valid while executing an `OptionSet`\nautocommand.", DocumentationSource: "eval.txt"},
	{Name: "v:option_old", Type: "string", Flags: VariableReadOnly, Documentation: "v:option_old    Old value of the option.  Valid while executing an `OptionSet`\nautocommand.  Depending on the command used for setting and\nthe kind of option this is either the local old value or the\nglobal old value.", DocumentationSource: "eval.txt"},
	{Name: "v:option_oldlocal", Type: "string", Flags: VariableReadOnly, Documentation: "v:option_oldlocal\nOld local value of the option.  Valid while executing an\n`OptionSet` autocommand.", DocumentationSource: "eval.txt"},
	{Name: "v:option_oldglobal", Type: "string", Flags: VariableReadOnly, Documentation: "v:option_oldglobal\nOld global value of the option.  Valid while executing an\n`OptionSet` autocommand.", DocumentationSource: "eval.txt"},
	{Name: "v:option_command", Type: "string", Flags: VariableReadOnly, Documentation: "v:option_command\nCommand used to set the option.  Valid while executing an\n`OptionSet` autocommand.\n### value\t\toption was set via\n\"setlocal\"\t`:setlocal` or \":let l:xxx\"\n\"setglobal\"\t`:setglobal` or \":let g:xxx\"\n\"set\"\t\t`:set` or `:let`\n\"modeline\"\t`modeline`", DocumentationSource: "eval.txt"},
	{Name: "v:option_type", Type: "string", Flags: VariableReadOnly, Documentation: "v:option_type   Scope of the set command.  Valid while executing an\n`OptionSet` autocommand.  Can be either \"global\" or \"local\"", DocumentationSource: "eval.txt"},
	{Name: "v:errors", Type: "list<string>", Flags: 0, Documentation: "v:errors\tErrors found by assert functions, such as `assert_true()`.\nThis is a list of strings.\nThe assert functions append an item when an assert fails.\nThe return value indicates this: a one is returned if an item\nwas added to v:errors, otherwise zero is returned.\nTo remove old results make it empty:\n```vim\n:let v:errors = []\n```\nIf v:errors is set to anything but a list it is made an empty\nlist by the assert function.", DocumentationSource: "eval.txt"},
	{Name: "v:false", Type: "bool", Flags: VariableReadOnly, Documentation: "v:false\t\tA Number with value zero.  Used to put \"false\" in JSON.  See\n`json_encode()`.\nWhen used as a string this evaluates to \"v:false\".\n```vim\n\t\techo v:false\n```\n### v:false\nThat is so that eval() can parse the string back to the same\nvalue.  Read-only.\nIn `Vim9` script \"false\" can be used which has a boolean type.", DocumentationSource: "eval.txt"},
	{Name: "v:true", Type: "bool", Flags: VariableReadOnly, Documentation: "v:true\t\tA Number with value one.  Used to put \"true\" in JSON.  See\n`json_encode()`.\nWhen used as a string this evaluates to \"v:true\".\n```vim\n\t\techo v:true\n```\n### v:true\nThat is so that eval() can parse the string back to the same\nvalue.  Read-only.\nIn `Vim9` script \"true\" can be used which has a boolean type.", DocumentationSource: "eval.txt"},
	{Name: "v:none", Type: "special", Flags: VariableReadOnly, Documentation: "v:none\t\tAn empty String.  Used to put an empty item in JSON.  See\n`json_encode()`.\nThis can also be used as a function argument to use the\ndefault value, see `none-function_argument`.\nWhen used as a number this evaluates to zero.\nWhen used as a string this evaluates to \"v:none\".\n```vim\n\t\techo v:none\n```\n### v:none\nThat is so that eval() can parse the string back to the same\nvalue.  Read-only.\nNote that using `== v:none` and `!= v:none`  will often give\nan error.  Instead, use `is v:none` and `isnot v:none` .", DocumentationSource: "eval.txt"},
	{Name: "v:null", Type: "special", Flags: VariableReadOnly, Documentation: "v:null\t\tAn empty String.  Used to put \"null\" in JSON.  See\n`json_encode()`.\nWhen used as a number this evaluates to zero.\nWhen used as a string this evaluates to \"v:null\".\n```vim\n\t\techo v:null\n```\n### v:null\nThat is so that eval() can parse the string back to the same\nvalue.  Read-only.\nIn `Vim9` script `null` can be used without \"v:\".\nIn some places `v:null` and `null` can be used for a List,\nDict, Job, etc. that is not set.  That is slightly different\nthan an empty List, Dict, etc.", DocumentationSource: "eval.txt"},
	{Name: "v:numbermax", Type: "number", Flags: VariableReadOnly, Documentation: "v:numbermax\tMaximum value of a number.", DocumentationSource: "eval.txt"},
	{Name: "v:numbermin", Type: "number", Flags: VariableReadOnly, Documentation: "v:numbermin\tMinimum value of a number (negative).", DocumentationSource: "eval.txt"},
	{Name: "v:numbersize", Type: "number", Flags: VariableReadOnly, Documentation: "v:numbersize\tNumber of bits in a Number.  This is normally 64, but on some\nsystems it may be 32.", DocumentationSource: "eval.txt"},
	{Name: "v:vim_did_enter", Type: "number", Flags: VariableReadOnly, Documentation: "v:vim_did_enter\tZero until most of startup is done.  It is set to one just\nbefore `VimEnter` autocommands are triggered.", DocumentationSource: "eval.txt"},
	{Name: "v:testing", Type: "number", Flags: 0, Documentation: "v:testing\tMust be set before using `test_garbagecollect_now()`.\nAlso, when set certain error messages won't be shown for 2\nseconds. (e.g. \"'dictionary' option is empty\")", DocumentationSource: "eval.txt"},
	{Name: "v:t_number", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_number\tValue of `Number` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_string", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_string\tValue of `String` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_func", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_func\tValue of `Funcref` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_list", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_list\tValue of `List` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_dict", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_dict\tValue of `Dictionary` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_float", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_float\tValue of `Float` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_bool", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_bool\tValue of `Boolean` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_none", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_none\tValue of `None` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_job", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_job\t\tValue of `Job` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_channel", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_channel\tValue of `Channel` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_blob", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_blob\tValue of `Blob` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_class", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_class\tValue of `class` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_object", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_object\tValue of `object` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:termrfgresp", Type: "string", Flags: VariableReadOnly, Documentation: "v:termrfgresp\tThe escape sequence returned by the terminal for the `t_RF`\ntermcap entry.  This is used to find out what the terminal\nforeground color is.  When this variable is set, the\nTermResponseAll autocommand event is fired, with <amatch> set\nto \"foreground\".", DocumentationSource: "eval.txt"},
	{Name: "v:termrbgresp", Type: "string", Flags: VariableReadOnly, Documentation: "v:termrbgresp\tThe escape sequence returned by the terminal for the `t_RB`\ntermcap entry.  This is used to find out what the terminal\nbackground color is; see 'background'.  When this variable is\nset, the TermResponseAll autocommand event is fired, with\n<amatch> set to \"background\".", DocumentationSource: "eval.txt"},
	{Name: "v:termu7resp", Type: "string", Flags: VariableReadOnly, Documentation: "v:termu7resp\tThe escape sequence returned by the terminal for the `t_u7`\ntermcap entry.  This is used to find out what the terminal\ndoes with ambiguous width characters, see 'ambiwidth'.  When\nthis variable is set, the TermResponseAll autocommand event is\nfired, with <amatch> set to \"ambiguouswidth\".", DocumentationSource: "eval.txt"},
	{Name: "v:termstyleresp", Type: "string", Flags: VariableReadOnly, Documentation: "v:termstyleresp\tThe escape sequence returned by the terminal for the `t_RS`\ntermcap entry.  This is used to find out what the shape of the\ncursor is.  This is used by `term_getcursor()`.  When this\nvariable is set, the TermResponseAll autocommand event is\nfired, with <amatch> set to \"cursorshape\".", DocumentationSource: "eval.txt"},
	{Name: "v:termblinkresp", Type: "string", Flags: VariableReadOnly, Documentation: "v:termblinkresp\tThe escape sequence returned by the terminal for the `t_RC`\ntermcap entry.  This is used to find out whether the terminal\ncursor is blinking.  This is used by `term_getcursor()`.  When\nthis variable is set, the TermResponseAll autocommand event is\nfired, with <amatch> set to \"cursorblink\".", DocumentationSource: "eval.txt"},
	{Name: "v:event", Type: "dict<any>", Flags: VariableReadOnly, Documentation: "v:event\t\tDictionary containing information about the current\n`autocommand`.  See the specific event for what it puts in\nthis dictionary.\nThe dictionary is emptied when the `autocommand` finishes,\nplease refer to `dict-identity` for how to get an independent\ncopy of it.  Use `deepcopy()` if you want to keep the\ninformation after the event triggers.  Example:\n```vim\n\t\tau TextYankPost * let g:foo = deepcopy(v:event)\n```", DocumentationSource: "eval.txt"},
	{Name: "v:versionlong", Type: "number", Flags: VariableReadOnly, Documentation: "v:versionlong\tLike v:version, but also including the patchlevel in the last\nfour digits.  Version 8.1 with patch 123 has value 8010123.\nThis can be used like this:\n```vim\n\t\tif v:versionlong >= 8010123\n```\nHowever, if there are gaps in the list of patches included\nthis will not work well.  This can happen if a recent patch\nwas included into an older version, e.g. for a security fix.\nUse the has() function to make sure the patch is actually\nincluded.", DocumentationSource: "eval.txt"},
	{Name: "v:echospace", Type: "number", Flags: VariableReadOnly, Documentation: "v:echospace\tNumber of screen cells that can be used for an `:echo` message\nin the last screen line before causing the `hit-enter-prompt`.\nDepends on 'showcmd', 'ruler' and 'columns'.  You need to\ncheck 'cmdheight' for whether there are full-width lines\navailable above the last line.", DocumentationSource: "eval.txt"},
	{Name: "v:argv", Type: "list<string>", Flags: VariableReadOnly, Documentation: "v:argv\t\tThe command line arguments Vim was invoked with.  This is a\nlist of strings.  The first item is the Vim command.\nSee `v:progpath` for the command with full path.", DocumentationSource: "eval.txt"},
	{Name: "v:collate", Type: "string", Flags: VariableReadOnly, Documentation: "v:collate\tThe current locale setting for collation order of the runtime\nenvironment.  This allows Vim scripts to be aware of the\ncurrent locale encoding.  Technical: it's the value of\nLC_COLLATE.  When not using a locale the value is \"C\".\nThis variable can not be set directly, use the `:language`\ncommand.\nSee `multi-lang`.", DocumentationSource: "eval.txt"},
	{Name: "v:exiting", Type: "special", Flags: VariableReadOnly, Documentation: "v:exiting\tVim exit code.  Normally zero, non-zero when something went\nwrong.  The value is v:null before invoking the `VimLeavePre`\nand `VimLeave` autocmds.  See `:q`, `:x` and `:cquit`.\nExample:\n```vim\n\t\t:au VimLeave * echo \"Exit value is \" .. v:exiting\n```", DocumentationSource: "eval.txt"},
	{Name: "v:colornames", Type: "dict<string>", Flags: VariableReadOnly, Documentation: "v:colornames\tA dictionary that maps color names to hex color strings.\nThese color names can be used with the `highlight-guifg`,\n`highlight-guibg`, and `highlight-guisp` parameters.\n\nThe key values in the dictionary (the color names) should be\nlower cased, because Vim looks up a color by its lower case\nname.\n\nUpdating an entry in v:colornames has no immediate effect on\nthe syntax highlighting.  The highlight commands (probably in\na colorscheme script) need to be re-evaluated in order to use\nthe updated color values.  For example:\n```vim\n\n\t    :let v:colornames['fuscia'] = '#cf3ab4'\n\t    :let v:colornames['mauve'] = '#915f6d'\n\t    :highlight Normal guifg=fuscia guibg=mauve\n```\n\nThis cannot be used to override the `cterm-colors` but it can\nbe used to override other colors.  For example, the X11 colors\ndefined in the `colors/lists/default.vim` (previously defined\nin `rgb.txt`).  When defining new color names in a plugin, the\nrecommended practice is to set a color entry only when it does\nnot already exist.  For example:\n```vim\n\n\t    :call extend(v:colornames, {\n\t\t\\ 'fuscia': '#cf3ab4',\n\t\t\\ 'mauve': '#915f6d,\n\t\t\\ }, 'keep')\n```\n\nUsing `extend()` with the 'keep' option updates each color only\nif it did not exist in `v:colornames`.  Doing so allows the\nuser to choose the precise color value for a common name\nby setting it in their `.vimrc`.\n\nIt is possible to remove entries from this dictionary but\ndoing so is NOT recommended, because it is disruptive to\nother scripts.  It is also unlikely to achieve the desired\nresult because the `:colorscheme` and `:highlight` commands\nwill both automatically load all `colors/lists/default.vim`\ncolor scripts.\n\nYou can make changes to that file, but make sure to add new\nkeys instead of updating existing ones, otherwise Vim will\nskip loading the file (thinking it hasn't been changed).", DocumentationSource: "eval.txt"},
	{Name: "v:sizeofint", Type: "number", Flags: VariableReadOnly, Documentation: "v:sizeofint\tNumber of bytes in an int.  Depends on how Vim was compiled.\nThis is only useful for deciding whether a test will give the\nexpected result.", DocumentationSource: "eval.txt"},
	{Name: "v:sizeoflong", Type: "number", Flags: VariableReadOnly, Documentation: "v:sizeoflong\tNumber of bytes in a long.  Depends on how Vim was compiled.\nThis is only useful for deciding whether a test will give the\nexpected result.", DocumentationSource: "eval.txt"},
	{Name: "v:sizeofpointer", Type: "number", Flags: VariableReadOnly, Documentation: "v:sizeofpointer\tNumber of bytes in a pointer.  Depends on how Vim was\ncompiled.  This is only useful for deciding whether a test\nwill give the expected result.", DocumentationSource: "eval.txt"},
	{Name: "v:maxcol", Type: "number", Flags: VariableReadOnly, Documentation: "v:maxcol\tMaximum line length.  Depending on where it is used it can be\nscreen columns, characters or bytes.  The value currently is\n2147483647 on all systems.", DocumentationSource: "eval.txt"},
	{Name: "v:python3_version", Type: "number", Flags: VariableReadOnly, Documentation: "v:python3_version\nVersion of Python 3 that Vim was built against.  When\nPython is loaded dynamically (`python-dynamic`), this version\nshould exactly match the Python library up to the minor\nversion (e.g.  3.10.2 and 3.10.3 are compatible as the minor\nversion is \"10\", whereas 3.9.4 and 3.10.3 are not compatible).\nWhen `python-stable-abi` is used, this will be the minimum\nPython version that you can use instead. (e.g. if\nv:python3_version indicates 3.9, you can use 3.9, 3.10, or\nanything above).\n\nThis number is encoded as a hex number following Python ABI\nversioning conventions.  Do the following to have a\nhuman-readable full version in hex:\n```vim\n\t\techo printf(\"%08X\", v:python3_version)\n```\nYou can obtain only the minor version by doing:\n```vim\n\t\techo and(v:python3_version>>16,0xff)\n```\nRead-only.", DocumentationSource: "eval.txt"},
	{Name: "v:t_typealias", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_typealias\tValue of `typealias` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_enum", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_enum\tValue of `enum` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:t_enumvalue", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_enumvalue\tValue of `enumvalue` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:stacktrace", Type: "list<dict<any>>", Flags: VariableReadOnly, Documentation: "v:stacktrace\tThe stack trace of the exception most recently caught and\nnot finished.  Refer to `getstacktrace()` for the structure of\nstack trace.  See also `v:exception`, `v:throwpoint`, and\n`throw-variables`.", DocumentationSource: "eval.txt"},
	{Name: "v:t_tuple", Type: "number", Flags: VariableReadOnly, Documentation: "v:t_tuple\tValue of `Tuple` type.  Read-only.  See: `type()`", DocumentationSource: "eval.txt"},
	{Name: "v:wayland_display", Type: "string", Flags: VariableReadOnly, Documentation: "v:wayland_display\nThe name of the Wayland display that Vim is connected to.\nEquivalent to the $WAYLAND_DISPLAY environment variable.\nIf this is empty, then Vim is not connected to any display.", DocumentationSource: "eval.txt"},
	{Name: "v:clipmethod", Type: "string", Flags: VariableReadOnly, Documentation: "v:clipmethod\tThe current method of accessing the clipboard that is being\nused.  Can either have the value of:\nwayland\t\tThe Wayland protocol is being used.\nx11\t\tX11 selections are being used.\nnone\t\tThe above methods are unavailable or\ncannot be used.\nIf it is set to a value not in the above list, then a\nclipboard provider with the given name is being used for the\nclipboard functionality.  See 'clipmethod' for more details.", DocumentationSource: "eval.txt"},
	{Name: "v:termda1", Type: "string", Flags: VariableReadOnly, Documentation: "v:termda1\tThe escape sequence returned by a primary device attributes\n(DA1) query from the terminal.  When this variable is set, the\nTermResponseAll autocommand event is fired, with <amatch> set\nto \"da1\".  Can be used to detect OSC 52 support in a terminal.", DocumentationSource: "eval.txt"},
	{Name: "v:termosc", Type: "string", Flags: VariableReadOnly, Documentation: "v:termosc\tThe escape sequence of the most recent OSC response received\nfrom the terminal.  When this variable is set, the\n`TermResponseAll` autocommand event is fired, with <amatch>\nset to \"osc\".", DocumentationSource: "eval.txt"},
	{Name: "v:vim_did_init", Type: "number", Flags: VariableReadOnly, Documentation: "v:vim_did_init\tZero until initialization is done.  It is set to one just\nafter `vimrc` is sourced and before `load-plugins`.", DocumentationSource: "eval.txt"},
	{Name: "v:clipproviders", Type: "dict<any>", Flags: VariableReadOnly, Documentation: "v:clipproviders\nA dictionary containing clipboard providers, see\n`clipboard-providers` for more information.", DocumentationSource: "eval.txt"},
}
